create table if not exists outbox_events(id uuid primary key,topic varchar(160) not null,event_key varchar(160) not null,payload varchar(16000) not null,created_at timestamptz not null,published_at timestamptz,attempts integer not null default 0,next_attempt_at timestamptz not null,last_error varchar(2000));create index if not exists idx_patient_registry_outbox on outbox_events(published_at,next_attempt_at,created_at);
